import { Play, Pause, RotateCcw, ChevronRight } from 'lucide-react';
import { cn } from '@/lib/utils';

interface ControlsProps {
    isPlaying: boolean;
    onTogglePlay: () => void;
    onStep: () => void;
    onReset: () => void;
    generation: number;
    speed: number;
    onSpeedChange: (speed: number) => void;
    currentPreset: string;
    onPresetChange: (preset: string) => void;
    presets: Record<string, { label: string }>;
}

export function Controls({
    isPlaying,
    onTogglePlay,
    onStep,
    onReset,
    generation,
    speed,
    onSpeedChange,
    currentPreset,
    onPresetChange,
    presets
}: ControlsProps) {
    return (
        <div className="absolute bottom-6 md:bottom-12 left-1/2 -translate-x-1/2 flex flex-col items-center gap-4 md:gap-6 z-50 w-full max-w-3xl px-4 md:px-6">
            {/* Preset Selector HUD */}
            <div className="flex flex-wrap justify-center gap-1.5 md:gap-2 bg-white/5 backdrop-blur-xl p-1.5 rounded-2xl border border-white/10 shadow-[0_8px_32px_rgba(0,0,0,0.5)]">
                {Object.entries(presets).map(([id, preset]) => (
                    <button
                        key={id}
                        onClick={() => onPresetChange(id)}
                        className={cn(
                            "px-3 py-2 md:px-4 md:py-2 rounded-xl text-[8px] md:text-[10px] font-bold uppercase tracking-[0.1em] md:tracking-[0.2em] transition-all duration-300",
                            currentPreset === id
                                ? "bg-white text-black shadow-[0_0_20px_rgba(255,255,255,0.3)]"
                                : "text-white/30 hover:text-white hover:bg-white/5"
                        )}
                    >
                        {preset.label}
                    </button>
                ))}
            </div>

            {/* Main Control Hub */}
            <div className="flex flex-col md:flex-row items-center gap-4 md:gap-8 bg-black/40 backdrop-blur-2xl px-6 py-4 md:px-10 md:py-5 rounded-3xl md:rounded-[2.5rem] border border-white/5 shadow-2xl ring-1 ring-white/10 w-full md:w-auto">
                {/* Stats & Actions Container for Mobile */}
                <div className="flex items-center justify-between w-full md:w-auto gap-4 md:gap-8">
                    {/* Stats Section */}
                    <div className="flex flex-col items-start md:pr-8 md:border-r border-white/10">
                        <span className="text-[8px] md:text-[10px] font-mono text-white/30 uppercase tracking-[0.2em] mb-0.5 md:mb-1">Iteration</span>
                        <span className="text-xl md:text-2xl font-black text-white tabular-nums tracking-tighter">
                            {generation.toLocaleString().padStart(4, '0')}
                        </span>
                    </div>

                    {/* Action Buttons */}
                    <div className="flex items-center gap-3 md:gap-5">
                        <button
                            onClick={onReset}
                            className="p-2 md:p-3 rounded-full hover:bg-white/10 text-white/40 hover:text-white transition-all group"
                            title="Re-seed Simulation"
                        >
                            <RotateCcw className="w-4 h-4 md:w-5 md:h-5 group-hover:rotate-180 transition-transform duration-500" />
                        </button>

                        <button
                            onClick={onTogglePlay}
                            className={cn(
                                "p-4 md:p-6 rounded-full transition-all duration-500 shadow-2xl relative group",
                                isPlaying
                                    ? "bg-white text-black scale-105"
                                    : "bg-blue-600 text-white hover:bg-blue-500 shadow-blue-500/20"
                            )}
                        >
                            {isPlaying ? <Pause className="w-5 h-5 md:w-6 md:h-6 fill-current" /> : <Play className="w-5 h-5 md:w-6 md:h-6 fill-current translate-x-0.5" />}
                        </button>

                        <button
                            onClick={onStep}
                            disabled={isPlaying}
                            className="p-2 md:p-3 rounded-full hover:bg-white/10 text-white/40 hover:text-white disabled:opacity-20 transition-all"
                            title="Step Forward"
                        >
                            <ChevronRight className="w-5 h-5 md:w-6 md:h-6" />
                        </button>
                    </div>
                </div>

                {/* Playback Settings */}
                <div className="flex flex-col items-start md:pl-8 md:border-l border-white/10 w-full md:min-w-[140px]">
                    <div className="flex justify-between w-full mb-1.5 md:mb-2 text-[8px] md:text-[10px]">
                        <span className="font-mono text-white/30 uppercase tracking-[0.2em]">Interval</span>
                        <span className="font-mono text-blue-400 font-bold">{speed}ms</span>
                    </div>
                    <input
                        type="range"
                        min="20"
                        max="1000"
                        step="20"
                        value={speed}
                        onChange={(e) => onSpeedChange(parseInt(e.target.value))}
                        className="w-full h-1.5 md:h-2 accent-blue-500 cursor-pointer opacity-80 hover:opacity-100 transition-opacity bg-white/10 rounded-lg appearance-none"
                    />
                </div>
            </div>
        </div>
    );
}

"use client";

import React, { Suspense } from 'react';
import { Canvas } from '@react-three/fiber';
import * as THREE from 'three';
import { OrbitControls, Stars, Environment } from '@react-three/drei';
import { useLife3d } from './useLife3d';
import { VoxelGrid } from './VoxelGrid';
import { Controls } from './Controls';
import { PRESETS } from './presets';
import { EffectComposer, Bloom, Noise, Vignette, ChromaticAberration } from '@react-three/postprocessing';

export default function Life_3d() {
    const [activePreset, setActivePreset] = React.useState('neural');

    const {
        grid,
        intensities,
        ages,
        dimensions,
        isPlaying,
        generation,
        speed,
        togglePlay,
        step,
        reset,
        setSpeed,
        updateRules,
    } = useLife3d({
        initialWidth: 40,
        initialHeight: 40,
        initialDepth: 40,
        initialDensity: PRESETS.neural.density,
        initialRules: PRESETS.neural.rules,
    });

    const handlePresetChange = (presetId: string) => {
        setActivePreset(presetId);
        const preset = PRESETS[presetId];
        updateRules(preset.rules);
        reset(dimensions.width, dimensions.height, dimensions.depth, preset.density, true);
    };

    return (
        <div className="relative w-full h-full bg-black overflow-hidden group">
            {/* R3F Canvas */}
            <Canvas shadows dpr={[1, 2]} camera={{ position: [35, 35, 35], fov: 45 }}>
                <OrbitControls
                    makeDefault
                    autoRotate={!isPlaying}
                    autoRotateSpeed={0.3}
                    enableDamping
                    dampingFactor={0.05}
                    minDistance={10}
                    maxDistance={100}
                />

                <color attach="background" args={['#010101']} />
                <fog attach="fog" args={['#010101', 50, 120]} />

                {/* Lighting - Brightened for better visibility */}
                <ambientLight intensity={0.8} />
                <pointLight position={[30, 40, 30]} intensity={3} color="#ffffff" />
                <spotLight position={[-30, 40, 30]} intensity={2.5} angle={0.4} penumbra={1} castShadow />

                <Environment preset="city" />

                {/* Simulation */}
                <Suspense fallback={null}>
                    <VoxelGrid grid={grid} intensities={intensities} ages={ages} dimensions={dimensions} />
                </Suspense>

                <Stars radius={150} depth={70} count={8000} factor={6} saturation={0} fade speed={0.2} />

                {/* Post-Processing */}
                <EffectComposer multisampling={4}>
                    <Bloom
                        luminanceThreshold={0.15}
                        mipmapBlur
                        intensity={1.8}
                        radius={0.5}
                    />
                    <Noise opacity={0.05} />
                    <Vignette eskil={false} offset={0.05} darkness={1.1} />
                    <ChromaticAberration
                        offset={new THREE.Vector2(0.004, 0.004)}
                        radialModulation={false}
                        modulationOffset={0}
                    />
                </EffectComposer>
            </Canvas>

            {/* Controls Overlay */}
            <Controls
                isPlaying={isPlaying}
                onTogglePlay={togglePlay}
                onStep={step}
                onReset={() => reset()}
                generation={generation}
                speed={speed}
                onSpeedChange={setSpeed}
                currentPreset={activePreset}
                onPresetChange={handlePresetChange}
                presets={PRESETS}
            />
        </div>
    );
}

import { useState, useEffect, useCallback, useRef } from 'react';
import { SimulationEngine, Life3dRules, Grid } from './SimulationEngine';

interface UseLife3dProps {
    initialWidth?: number;
    initialHeight?: number;
    initialDepth?: number;
    initialDensity?: number;
    initialRules?: Life3dRules;
}

export function useLife3d({
    initialWidth = 20,
    initialHeight = 20,
    initialDepth = 20,
    initialDensity = 0.12,
    initialRules = { survival: [4, 5], birth: [5] }
}: UseLife3dProps = {}) {
    const [grid, setGrid] = useState<Grid>(new Uint8Array(0));
    const [intensities, setIntensities] = useState<Float32Array>(new Float32Array(0));
    const [ages, setAges] = useState<Uint16Array>(new Uint16Array(0));
    const [dimensions, setDimensions] = useState({ width: initialWidth, height: initialHeight, depth: initialDepth });
    const [isPlaying, setIsPlaying] = useState(false);
    const [speed, setSpeed] = useState(100);
    const [rules, setRules] = useState<Life3dRules>(initialRules);
    const [generation, setGeneration] = useState(0);

    const engineRef = useRef<SimulationEngine | null>(null);
    const timerRef = useRef<NodeJS.Timeout | null>(null);

    const reset = useCallback((w = dimensions.width, h = dimensions.height, d = dimensions.depth, density = initialDensity, shouldPlay = false) => {
        const engine = new SimulationEngine(w, h, d, rules);
        engine.seed(density);
        engineRef.current = engine;
        setGrid(new Uint8Array(engine.getGrid()));
        setIntensities(new Float32Array(engine.getIntensities()));
        setAges(new Uint16Array(engine.getAges()));
        setDimensions({ width: w, height: h, depth: d });
        setGeneration(0);
        setIsPlaying(shouldPlay);
    }, [dimensions.width, dimensions.height, dimensions.depth, rules, initialDensity, setIsPlaying]);

    useEffect(() => {
        reset();
        return () => {
            if (timerRef.current) clearInterval(timerRef.current);
        };
    }, [reset]);

    const step = useCallback(() => {
        if (engineRef.current) {
            engineRef.current.step();
            setGrid(new Uint8Array(engineRef.current.getGrid()));
            setIntensities(new Float32Array(engineRef.current.getIntensities()));
            setAges(new Uint16Array(engineRef.current.getAges()));
            setGeneration(prev => prev + 1);
        }
    }, []);

    useEffect(() => {
        if (isPlaying) {
            timerRef.current = setInterval(step, speed);
        } else {
            if (timerRef.current) clearInterval(timerRef.current);
        }
        return () => {
            if (timerRef.current) clearInterval(timerRef.current);
        };
    }, [isPlaying, speed, step]);

    const togglePlay = () => setIsPlaying(prev => !prev);

    const updateRules = (newRules: Life3dRules) => {
        setRules(newRules);
        if (engineRef.current) {
            engineRef.current.rules = newRules;
        }
    };

    return {
        grid,
        intensities,
        ages,
        dimensions,
        isPlaying,
        generation,
        speed,
        rules,
        togglePlay,
        step,
        reset,
        setSpeed,
        updateRules,
    };
}

import React, { useRef, useMemo, useEffect } from 'react';
import * as THREE from 'three';
import { useFrame } from '@react-three/fiber';

interface VoxelGridProps {
    grid: Uint8Array;
    intensities: Float32Array;
    ages: Uint16Array;
    dimensions: { width: number; height: number; depth: number };
}

export function VoxelGrid({ grid, intensities, ages, dimensions }: VoxelGridProps) {
    const meshRef = useRef<THREE.InstancedMesh>(null);
    const { width, height, depth } = dimensions;
    const count = width * height * depth;

    const tempObject = useMemo(() => new THREE.Object3D(), []);
    const tempColor = useMemo(() => new THREE.Color(), []);

    // Update instances when grid changes
    useEffect(() => {
        if (!meshRef.current) return;

        let instanceIndex = 0;

        for (let z = 0; z < depth; z++) {
            for (let y = 0; y < height; y++) {
                for (let x = 0; x < width; x++) {
                    const idx = x + y * width + z * width * height;
                    const intensity = intensities[idx];

                    if (intensity > 0.01) {
                        const age = ages[idx];

                        // Coordinate-based banding (Cyan/Pink/Yellow)
                        const nx = x / width;
                        const ny = y / height;

                        // Bands: 
                        // - Top (ny > 0.8): Cream/Yellow
                        // - Bottom Left (nx < 0.5): Magenta/Pink
                        // - Bottom Right (nx >= 0.5): Cyan/Teal

                        if (ny > 0.75) {
                            tempColor.set('#fff176'); // Top: Pale Yellow
                        } else if (nx < 0.5) {
                            tempColor.set('#ff007f'); // Left: Hot Pink
                        } else {
                            tempColor.set('#00ffff'); // Right: Cyan
                        }

                        // Age highlights: Newborns are brighter/white
                        if (age < 2) {
                            tempColor.lerp(new THREE.Color('#ffffff'), 0.8);
                        }

                        // Persistence (Ghosting): Fade color to black based on intensity
                        tempColor.multiplyScalar(intensity);

                        tempObject.position.set(
                            x - width / 2 + 0.5,
                            y - height / 2 + 0.5,
                            z - depth / 2 + 0.5
                        );

                        // Base scale is smaller for ghostly cells
                        const baseScale = intensity * 0.45;
                        tempObject.scale.setScalar(baseScale);
                        tempObject.updateMatrix();

                        meshRef.current.setMatrixAt(instanceIndex, tempObject.matrix);
                        meshRef.current.setColorAt(instanceIndex, tempColor);

                        instanceIndex++;
                    }
                }
            }
        }

        // Hide remaining instances
        for (let i = instanceIndex; i < count; i++) {
            tempObject.position.set(0, 1000, 0); // Move out of view
            tempObject.scale.setScalar(0);
            tempObject.updateMatrix();
            meshRef.current.setMatrixAt(i, tempObject.matrix);
        }

        meshRef.current.instanceMatrix.needsUpdate = true;
        if (meshRef.current.instanceColor) {
            meshRef.current.instanceColor.needsUpdate = true;
        }
        meshRef.current.count = instanceIndex;
    }, [grid, intensities, ages, width, height, depth, count, tempObject, tempColor]);

    // Pulsing animation
    useFrame((state) => {
        if (!meshRef.current) return;
        const t = state.clock.getElapsedTime();

        // Subtle breathing effect on the whole group
        meshRef.current.rotation.y = Math.sin(t * 0.1) * 0.05;
        meshRef.current.scale.setScalar(1 + Math.sin(t * 0.5) * 0.02);
    });

    return (
        <group>
            <instancedMesh ref={meshRef} args={[undefined, undefined, count]}>
                <icosahedronGeometry args={[0.5, 0]} />
                <meshStandardMaterial
                    toneMapped={false}
                    emissiveIntensity={4}
                    metalness={1.0}
                    roughness={0.05}
                />
            </instancedMesh>

            {/* Boundary Box - Sharp & Technical wireframe */}
            <mesh>
                <boxGeometry args={[width, height, depth]} />
                <meshBasicMaterial color="#ffffff" wireframe transparent opacity={0.1} />
            </mesh>
        </group>
    );
}

